        return { ok: true, entry: { ref: entry.ref, name: entry.name, mimeType: entry.mimeType, ext: entry.ext, size: entry.size, createdAt: entry.createdAt, realPath: entry.realPath ? s(entry.realPath) : null }, base64: base64 }
